import grackle.{Result, ScalarType, Schema}

val schema = Schema(
  """
    scalar UUID @specifiedBy(url: "https://tools.ietf.org/html/rfc4122")
    type Query {
      user(id: UUID!): UUID
    }
  """
)

schema match {
  case Result.Success(s) =>
    val uuid = s.baseTypes.find(_.name == "UUID").get.asInstanceOf[ScalarType]
    uuid.specifiedByURL  // Some("https://tools.ietf.org/html/rfc4122")
  case _ => ???
}

