      products: [String!]!
      user: User! @authenticated
    }
    type User {
      name: String!
      email: String! @hasRole(requires: ADMIN)
    }
    directive @authenticated on FIELD_DEFINITION | OBJECT
    directive @hasRole(requires: Role = ADMIN) on FIELD_DEFINITION | OBJECT
