import grackle.{GraphQLParser, SchemaParser}
import grackle.syntax._

val parser       = GraphQLParser(GraphQLParser.defaultConfig)
val schemaParser = SchemaParser(parser)

val sdl =
  """|type Query {
     |  posts: [Post]
     |  author(id: Int! = 23): Author
     |}
     |type Post {
     |  id: Int!
     |  title: String
     |}
     |type Author {
     |  id: Int!
     |}""".stripMargin

val rendered = schemaParser.parseText(sdl).map(_.toString)
// rendered == sdl.success
